@ExtendWith(MockitoExtension.class)
@DisplayName("AuthService Unit Tests")
class AuthServiceTest {

    @Mock
    private UserRepository userRepository;

    @Mock
    private PasswordEncoder passwordEncoder;

    @Mock
    private JwtTokenProvider jwtTokenProvider;

    @Mock
    private AuthenticationManager authenticationManager;

    @InjectMocks
    private AuthService authService;

    private User sampleUser;
    private LoginRequest loginRequest;
    private RegisterRequest registerRequest;

    @BeforeEach
    void setUp() {
        sampleUser = User.builder()
                .id(1L)
                .username("testuser")
                .email("testuser@example.com")
                .password("encoded_password")
                .roles(Set.of(Role.ROLE_USER))
                .enabled(true)
                .build();

        loginRequest = new LoginRequest("testuser", "raw_password");
        registerRequest = new RegisterRequest("newuser", "newuser@example.com", "password123");
    }

    @Nested
    @DisplayName("User Registration Tests")
    class RegistrationTests {

        @Test
        @DisplayName("Should successfully register a new user")
        void register_Success() {
            given(userRepository.existsByUsername(registerRequest.getUsername())).willReturn(false);
            given(userRepository.existsByEmail(registerRequest.getEmail())).willReturn(false);
            given(passwordEncoder.encode(registerRequest.getPassword())).willReturn("encoded_password123");

            User savedUser = User.builder()
                    .id(2L)
                    .username(registerRequest.getUsername())
                    .email(registerRequest.getEmail())
                    .password("encoded_password123")
                    .roles(Set.of(Role.ROLE_USER))
                    .enabled(true)
                    .build();

            given(userRepository.save(any(User.class))).willReturn(savedUser);
            given(jwtTokenProvider.generateToken(any(User.class))).willReturn("jwt.mock.token");
            given(jwtTokenProvider.generateRefreshToken(any(User.class))).willReturn("jwt.mock.refresh-token");

            AuthResponse response = authService.register(registerRequest);

            assertNotNull(response);
            assertEquals("jwt.mock.token", response.getAccessToken());
            assertEquals("jwt.mock.refresh-token", response.getRefreshToken());
            assertEquals("newuser", response.getUsername());

            ArgumentCaptor<User> userCaptor = ArgumentCaptor.forClass(User.class);
            verify(userRepository).save(userCaptor.capture());
            User capturedUser = userCaptor.getValue();
            assertEquals("newuser", capturedUser.getUsername());
            assertEquals("encoded_password123", capturedUser.getPassword());
            assertTrue(capturedUser.getRoles().contains(Role.ROLE_USER));
        }

        @Test
        @DisplayName("Should throw exception when username is already taken")
        void register_DuplicateUsername_ThrowsException() {
            given(userRepository.existsByUsername(registerRequest.getUsername())).willReturn(true);

            assertThrows(UserAlreadyExistsException.class, () -> authService.register(registerRequest));
            verify(userRepository, never()).save(any(User.class));
        }

        @Test
        @DisplayName("Should throw exception when email is already in use")
        void register_DuplicateEmail_ThrowsException() {
            given(userRepository.existsByUsername(registerRequest.getUsername())).willReturn(false);
            given(userRepository.existsByEmail(registerRequest.getEmail())).willReturn(true);

            assertThrows(UserAlreadyExistsException.class, () -> authService.register(registerRequest));
            verify(userRepository, never()).save(any(User.class));
        }
    }

    @Nested
    @DisplayName("User Authentication & Login Tests")
    class AuthenticationTests {

        @Test
        @DisplayName("Should authenticate user and return tokens when credentials are valid")
        void login_Success() {
            Authentication authentication = mock(Authentication.class);
            given(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
                    .willReturn(authentication);
            given(userRepository.findByUsername(loginRequest.getUsername()))
                    .willReturn(Optional.of(sampleUser));
            given(jwtTokenProvider.generateToken(sampleUser)).willReturn("valid.access.token");
            given(jwtTokenProvider.generateRefreshToken(sampleUser)).willReturn("valid.refresh.token");

            AuthResponse response = authService.login(loginRequest);

            assertNotNull(response);
            assertEquals("valid.access.token", response.getAccessToken());
            assertEquals("valid.refresh.token", response.getRefreshToken());
            assertEquals("testuser", response.getUsername());
            verify(authenticationManager).authenticate(
