            given(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
                    .willThrow(new org.springframework.security.authentication.BadCredentialsException("Invalid credentials"));

            assertThrows(BadCredentialsException.class, () -> authService.login(loginRequest));
            verify(jwtTokenProvider, never()).generateToken(any());
        }

        @Test
        @DisplayName("Should throw UserNotFoundException when authenticated user not found in DB")
        void login_UserNotFoundAfterAuth_ThrowsException() {
            Authentication authentication = mock(Authentication.class);
            given(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
                    .willReturn(authentication);
            given(userRepository.findByUsername(loginRequest.getUsername()))
                    .willReturn(Optional.empty());

            assertThrows(UserNotFoundException.class, () -> authService.login(loginRequest));
