    }

    @Nested
    @DisplayName("JWT Token Validation and Expiration Tests")
    class TokenValidationTests {

        @Test
        @DisplayName("Should successfully refresh token when refresh token is valid")
        void refreshToken_ValidToken_Success() {
            String refreshToken = "valid.refresh.jwt";
            given(jwtTokenProvider.validateToken(refreshToken)).willReturn(true);
            given(jwtTokenProvider.isTokenExpired(refreshToken)).willReturn(false);
            given(jwtTokenProvider.getUsernameFromToken(refreshToken)).willReturn("testuser");
            given(userRepository.findByUsername("testuser")).willReturn(Optional.of(sampleUser));
            given(jwtTokenProvider.generateToken(sampleUser)).willReturn("new.access.token");
            given(jwtTokenProvider.generateRefreshToken(sampleUser)).willReturn("new.refresh.token");

