            given(jwtTokenProvider.validateToken(expiredRefreshToken)).willReturn(true);
            given(jwtTokenProvider.isTokenExpired(expiredRefreshToken)).willReturn(true);

            assertThrows(TokenExpiredException.class, () -> authService.refreshToken(expiredRefreshToken));
            verify(userRepository, never()).findByUsername(anyString());
        }

        @Test
        @DisplayName("Should throw BadCredentialsException when refresh token is invalid or malformed")
        void refreshToken_InvalidToken_ThrowsException() {
            String invalidToken = "malformed.jwt.token";
            given(jwtTokenProvider.validateToken(invalidToken)).willReturn(false);

            assertThrows(BadCredentialsException.class, () -> authService.refreshToken(invalidToken));
            verify(jwtTokenProvider, never()).getUsernameFromToken(anyString());
        }

        @Test
        @DisplayName("Should validate token expiration boundary accurately")
        void validateTokenExpiration_BoundaryCheck() {
            String validToken = "boundary.test.token";
            Date futureExpiration = new Date(System.currentTimeMillis() + 3600000);
            Date pastExpiration = new Date(System.currentTimeMillis() - 1000);

            given(jwtTokenProvider.getExpirationDateFromToken(validToken)).willReturn(futureExpiration);
            assertFalse(jwtTokenProvider.getExpirationDateFromToken(validToken).before(new Date()));

            given(jwtTokenProvider.getExpirationDateFromToken("expired.token")).willReturn(pastExpiration);
            assertTrue(jwtTokenProvider.getExpirationDateFromToken("expired.token").before(new Date()));
        }
    }
