## 5. Type Definitions & Contract Designs

### Target: `src/types/metrics.ts`
```typescript
export type MetricType = 'cpu' | 'memory' | 'network' | 'latency' | 'throughput' | 'errors';

export type HealthStatus = 'healthy' | 'degraded' | 'critical' | 'unknown';

export type ConnectionStatus = 'connecting' | 'connected' | 'disconnected' | 'reconnecting' | 'error';

export interface MetricTelemetryPoint {
  metricId: string;
  type: MetricType;
  timestamp: number;
  value: number;
  unit: string;
  tags?: Record<string, string>;
}

export interface MetricSeries {
  metricId: string;
  type: MetricType;
  name: string;
  unit: string;
  points: MetricTelemetryPoint[];
  latestValue: number;
  min: number;
  max: number;
  avg: number;
  status: HealthStatus;
}

export interface SystemHealth {
  overall: HealthStatus;
  score: number; // 0-100
  activeAlertCount: number;
  lastUpdated: number;
}

export interface TelemetryAlert {
  id: string;
  metricId: string;
  type: MetricType;
  severity: 'info' | 'warning' | 'critical';
  message: string;
  timestamp: number;
  acknowledged: boolean;
}

export interface SubscriptionConfig {
  topic: string;
  metricType: MetricType;
  intervalMs: number;
  enabled: boolean;
}

export interface WebSocketMessage<T = unknown> {
  type: 'SUBSCRIBE' | 'UNSUBSCRIBE' | 'TELEMETRY' | 'ACK' | 'PING' | 'PONG' | 'ERROR';
  requestId?: string;
  topic?: string;
  timestamp?: number;
  data?: T;
  error?: string;
}
